        $body = @{ limitidentifier = $Limitidentifier }
        if ($PSBoundParameters.ContainsKey('Alertsintimeslice')) { $body['alertsintimeslice'] = $true }
        if ($PSBoundParameters.ContainsKey('LimitType')) { $body['limittype'] = $true }
        if ($PSBoundParameters.ContainsKey('MaxBandwidth')) { $body['maxbandwidth'] = $true }
        if ($PSBoundParameters.ContainsKey('Mode')) { $body['mode'] = $true }
        if ($PSBoundParameters.ContainsKey('SelectorName')) { $body['selectorname'] = $true }
        if ($PSBoundParameters.ContainsKey('Threshold')) { $body['threshold'] = $true }
        if ($PSBoundParameters.ContainsKey('Timealign')) { $body['timealign'] = $true }
        if ($PSBoundParameters.ContainsKey('Timeslice')) { $body['timeslice'] = $true }
        if ($PSBoundParameters.ContainsKey('TrapSintimeslice')) { $body['trapsintimeslice'] = $true }

        if ($body.Count -le 1) {
            throw 'Specify at least one property switch to clear.'
        }

        if ($PSCmdlet.ShouldProcess("$Limitidentifier", 'Clear nslimitidentifier properties')) {
            $response = Invoke-NSRestRequest @transportParameters -Session $Session -Method POST -Task config -Type nslimitidentifier -Action unset -Payload @{ nslimitidentifier = $body } -RawResponse

            if ($PassThru) {
