    if ($PSBoundParameters.ContainsKey('Iffull')) { $properties['iffull'] = $Iffull }
    if ($PSBoundParameters.ContainsKey('Ifnovalue')) { $properties['ifnovalue'] = $Ifnovalue }
    if ($PSBoundParameters.ContainsKey('Ifvaluetoobig')) { $properties['ifvaluetoobig'] = $Ifvaluetoobig }
    if ($PSBoundParameters.ContainsKey('Init')) { $properties['init'] = $Init }
    if ($PSBoundParameters.ContainsKey('Name')) { $properties['name'] = $Name }
    if ($PSBoundParameters.ContainsKey('Type')) { $properties['type'] = $Type }

    $body = [System.Collections.Generic.Dictionary[string, object]]::new([System.StringComparer]::Ordinal)
    foreach ($key in $properties.Keys) {
        if ($null -ne $properties[$key] -and (-not ($properties[$key] -is [string]) -or $properties[$key] -ne '')) {
            $body[$key] = $properties[$key]
        }
    }

    if ($PSCmdlet.ShouldProcess("$Name", 'Update nsvariable')) {
        $response = Invoke-NSRestRequest @transportParameters -Session $Session -Method PUT -Task config -Type nsvariable -Payload @{ nsvariable = $body } -RawResponse

